#!/usr/bin/env python3
"""Independent read-only verification of the ten exact enrolled chain joins."""
from pathlib import Path
import json,hashlib,argparse
H=Path(__file__).resolve().parent;p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();cat=json.loads((H/'recipe/input-pins.json').read_text());D=Path('/tmp/bendvy-descending-generated-frozen-v1');e=json.loads((D/'evidence.json').read_text());assert e['status']=='FROZEN_TEN_EXACT_CHAIN_PROGRAMS_PASS';assert all(sha(Path(n))==h for n,h in {**e['recipes'],**e['catalogs']}.items());r={'status':'INCOMPLETE','scope':'Exact enrolled ten source/build/row/pool/tuple joins; not general provenance inference by selective rewrite','priorReceiptSHA256':sha(D/'evidence.json'),'currentProducerPins':e['recipes'],'currentCatalogPins':e['catalogs'],'programs':[]}
for digest,pin in cat.items():
 label=pin['label'];assert sha(Path(pin['inputPath']))==digest and all(sha(Path(n))==h for n,h in pin['files'].items());assert all(sha(Path(pin['sourceRoot'])/n)==h for n,h in pin['sourcePins'].items());program=next(x for x in e['programs'] if x['label']==label);assert program['finalSHA256']==digest
 stages={role:json.loads((D/(label+'-'+role+'.js.recipe.json')).read_text()) for role in ['row','pool','tuple']};row,pool,tu=stages.values();assert row['inputSHA256']==program['sourceSHA256'];assert row['outputSHA256']==pool['inputSHA256']==program['rowSHA256'];assert pool['outputSHA256']==tu['inputSHA256']==program['poolSHA256'];assert tu['outputSHA256']==digest
 for role,m in stages.items():
  assert m['sourceRoot']==pin['sourceRoot'] and m['sourcePins']==pin['sourcePins'];assert sha(D/(label+'-'+role+'.js'))==m['outputSHA256'];assert m['recipeSHA256'] in e['recipes'].values() and m['catalogSHA256'] in e['catalogs'].values();catalogPath=next(Path(n) for n,h in e['catalogs'].items() if h==m['catalogSHA256']);enrolled=json.loads(catalogPath.read_text())[m['inputSHA256']];assert enrolled['sourceRoot']==pin['sourceRoot'] and enrolled['sourcePins']==pin['sourcePins']
 r['programs'].append({'label':label,'sourceRoot':pin['sourceRoot'],'sourcePins':pin['sourcePins'],'originalJS':row['inputSHA256'],'rowOutput':row['outputSHA256'],'poolOutput':pool['outputSHA256'],'tupleOutput':digest,'receiptPins':{role:sha(D/(label+'-'+role+'.js.recipe.json')) for role in stages}})
assert len(r['programs'])==10;r['status']='INDEPENDENT_TEN_EXACT_PRIOR_CHAIN_JOINS_CURRENT_RECIPES_CATALOGS_SOURCE_PASS';a.output.write_text(json.dumps(r,indent=2)+'\n')
